sited.script:

const baseUrl = "https://123av.com";

function home_list_parse(url, html){
    var $ = cheerio.load(html);
    var list = [];

    // 1. 解析多區塊 (新發布、最近添加等)
    $('section, .section, div').each(function() {
        var $$ = cheerio.load($(this).html());
        var group_name = $$('h2.section__title').first().text().trim();
        if (group_name) {
            var gName = gbk2big5.traditionalized(group_name);
            $$('.card').each(function() {
                var card = cheerio(this);
                var link = card.find('a.card__cover, a.card__link');
                var href = link.attr('href');
                var title = card.find('.card__title').text().trim();
                var img = card.find('.card__img').attr('src') || card.find('.card__img').attr('data-src');
                if (href && title && list.none ? true : !list.some(function(item) { return item.url === baseUrl + href && item.group === gName; })) {
                    list.push({
                        group: gName,
                        url: baseUrl + href,
                        name: gbk2big5.traditionalized(title),
                        logo: img
                    });
                }
            });
        }
    });

    // 2. 若無分組，後備抓取所有卡片
    if (list.length === 0) {
        $('.card').each(function() {
            var $$ = cheerio.load($(this).html());
            var link = $$('.card__title a.card__link, a.card__cover');
            var href = link.attr('href');
            var title = $$('.card__title').text().trim();
            var img = $$('.card__img').attr('src') || $$('.card__img').attr('data-src');
            if (href && title) {
                list.push({
                    group: "最新影片",
                    url: baseUrl + href,
                    name: gbk2big5.traditionalized(title),
                    logo: img
                });
            }
        });
    }

    return JSON.stringify(list);
}

// 核心的「內容列表」解析函式（搜尋與標籤列表頁）
function list_parse(url, html){
    var $ = cheerio.load(html);
    var list = [];

    $('.card').each(function() {
        var $$ = cheerio.load($(this).html());
        var link = $$('.card__title a.card__link, a.card__cover');
        var href = link.attr('href');
        var title = $$('.card__title').text().trim();
        var img = $$('.card__img').attr('src') || $$('.card__img').attr('data-src');
        if (href && title) {
            list.push({
                url: baseUrl + href,
                name: gbk2big5.traditionalized(title),
                logo: img
            });
        }
    });

    return JSON.stringify(list);
}

function section_parse(url, html) {
    return JSON.stringify({type:"webview", data: url});
}

sited.WebViewInjection:

            javascript:(function() {
    let intervalId = null;

    function runInjection() {
        try {
            var player = document.querySelector('.player, .watch__main, iframe.player__frame');
            var title = document.querySelector('.watch__title, h1');

            if (player) {
                document.body.style.visibility = 'hidden';

                var current = player;
                while (current && current.tagName !== 'BODY') {
                    current.style.visibility = 'visible';
                    var siblings = Array.from(current.parentNode.children);
                    siblings.forEach(function(sibling) {
                        if (sibling !== current) {
                            sibling.style.display = 'none';
                        }
                    });
                    current = current.parentElement;
                }

                if (title) {
                    var currentTitle = title;
                    while (currentTitle && currentTitle.tagName !== 'BODY') {
                        currentTitle.style.visibility = 'visible';
                        currentTitle.style.display = 'block';
                        currentTitle = currentTitle.parentElement;
                    }
                }

                document.body.style.visibility = 'visible';
                document.body.style.margin = '0';
                document.body.style.padding = '0';

                return true;
            } else {
                return false;
            }
        } catch (e) {
            return false;
        }
    }

    intervalId = setInterval(function() {
        if (runInjection()) {
            clearInterval(intervalId);
        }
    }, 1000);

    setTimeout(function() {
        if (intervalId !== null) {
            clearInterval(intervalId);
        }
    }, 15000);
})();
